function updateDemixer(W, X, mask, eta) {
  // X: mixed signals, mask: observed=@1 or missing=@0
  const Xeff = X.map((xi,i)=> mask[i]? xi: 0);
  // gradient on demixing matrix W with masked SGD
  const Y = W * Xeff; // simplified
  // ... compute loss and apply gradient
  // W = W - eta * grad
  return W;
}
